            confidenceLow = c.confidenceLow,
            confidenceMedium = c.confidenceMedium,
            confidenceHigh = c.confidenceHigh,
            focusRing = c.focusRing,
            overlayScrim = c.overlayScrim,
            data1 = c.data1,
            data2 = c.data2,
            data3 = c.data3,
            data4 = c.data4,
            data5 = c.data5,
        )
        return MonarchThemeTokens(id, isDark, isHighContrast, focusRingWidth, next, shadows)
    }
}

